import { MakeLogicType, actions, events, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'

export interface ConnectedApp {
    id: string
    name: string
    logo_uri: string | null
    scopes: string[]
    authorized_at: string
    is_verified: boolean
    is_first_party: boolean
    is_setup_wizard: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface connectedAppsLogicValues {
    connectedApps: ConnectedApp[]
    connectedAppsLoading: boolean
    hasConnectedAgent: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface connectedAppsLogicActions {
    loadConnectedApps: () => any
    loadConnectedAppsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadConnectedAppsSuccess: (
        connectedApps: ConnectedApp[],
        payload?: any
    ) => {
        connectedApps: ConnectedApp[]
        payload?: any
    }
    revokeApp: (id: string) => {
        id: string
    }
    revokeAppFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    revokeAppSuccess: (
        connectedApps: ConnectedApp[],
        payload?: {
            id: string
        }
    ) => {
        connectedApps: ConnectedApp[]
        payload?: {
            id: string
        }
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface connectedAppsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasConnectedAgent: (connectedApps: ConnectedApp[]) => boolean
    }
}

export type connectedAppsLogicType = MakeLogicType<
    connectedAppsLogicValues,
    connectedAppsLogicActions,
    Record<string, any>,
    connectedAppsLogicMeta
>

export const connectedAppsLogic = kea<connectedAppsLogicType>([
    path(['scenes', 'settings', 'user', 'connectedAppsLogic']),

    actions({
        revokeApp: (id: string) => ({ id }),
    }),

    loaders(({ values }) => ({
        connectedApps: [
            [] as ConnectedApp[],
            {
                loadConnectedApps: async () => {
                    // nosemgrep: prefer-codegen-api -- Legacy raw API call with a hand-written URL and an unchecked response type. No generated function covers this endpoint yet. Find out why the generated client skips it (no schema, no product tag, or excluded from the spec) and fix that first.
                    return await api.get('api/oauth/connected-apps/')
                },
                revokeApp: async ({ id }, breakpoint) => {
                    const remainingApps = values.connectedApps.filter((app) => app.id !== id)
                    // nosemgrep: prefer-codegen-api -- Legacy raw API call with a hand-written URL and an unchecked response type. No generated function covers this endpoint yet. Find out why the generated client skips it (no schema, no product tag, or excluded from the spec) and fix that first.
                    await api.create(`api/oauth/connected-apps/${id}/revoke/`)
                    breakpoint()
                    lemonToast.success('App access revoked')
                    return remainingApps
                },
            },
        ],
    })),

    selectors({
        // The MCP server signs agents in through OAuth, and the API does not tell an MCP client apart
        // from other OAuth apps, so any connection counts. The setup wizard is left out because it signs
        // in to install the SDK, before the user has connected an agent.
        hasConnectedAgent: [
            (s) => [s.connectedApps],
            (connectedApps: ConnectedApp[]): boolean => connectedApps.some((app) => !app.is_setup_wizard),
        ],
    }),

    events(({ actions }) => ({
        afterMount: () => actions.loadConnectedApps(),
    })),
])
